        osAdminUnlockPlan: { label: "Plán OS / admin odemčení", hint: "Jak se nájemce dostane přes login, firmware nebo MDM zámek — zmrazit před rezervací." },
        outdoorApRating: { label: "Venkovní rating AP", hint: "Jen indoor vs outdoor IP-rated. Not applicable u ne-AP zařízení." },
        phantomPowerSupport: { label: "Phantom power (48V)", hint: "Kondenzátory potřebují 48V. Uveďte zda jednotka dodává, potřebuje externí, nemá, nebo N/A." },
        pixelPitchMmBand: { label: "LED pixel pitch (mm)", hint: "Soft-povinné u LED cabinet stěn. Pozorovací vzdálenost a ostrost závisí na pitch." },
        poeBudgetBand: { label: "PoE rozpočet", hint: "Celkový dostupný PoE výkon (nebo žádný). Předchází podpájení AP/kamer." },
        portCountBand: { label: "Pásmo počtu portů", hint: "Škála copper/SFP portů — nebo jen wireless u AP/mesh bez switch portů." },
        powerBatteryPlateBand: { label: "Napájení / battery plate", hint: "Jen AC vs V-mount / Gold-mount / NP-F / USB-C PD — na lokaci bez toho show stojí." },
        powerCircuitBand: { label: "Napájení / okruh", hint: "Zásuvka 15A vs vyhrazený 20A vs 208/240V vs multi-circuit LED — zabrání výpadkům v den akce." },
        powerCircuitNotes: { label: "Poznámky k napájení / okruhu", hint: "Volitelné, ale doporučené: odběr ampér, distro, soft-start nebo předpoklady venue okruhu.", placeholder: "~6A @ 120V na cabinet; potřebuje vyhrazený 20A; ne řetězit víc než 4 cabinetty..." },
        proAudioCableLoom: { label: "Inventář kabelového loomu (XLR / TRS / digitál)", hint: "Spočítejte každý kabel — XLR, TRS, USB-C, Thunderbolt, ADAT, napájení. Zmrazeno při rezervaci; spočet při předání.", placeholder: "2× XLR 3 m, 2× TRS 2 m, 1× USB-C 1 m, IEC..." },
        proAudioGearType: { label: "Typ pro audio zařízení", hint: "Interface vs mixer vs mikrofon vs monitor — ne live PA stack (to je Music → PA Systems)." },
        projectorInputInventory: { label: "Inventář HDMI / vstupů", hint: "Vypište každý port a přiložený kabel/adaptér — počet HDMI, VGA, USB-C, wireless, audio out.", placeholder: "2× HDMI in, 1× VGA, 3.5mm audio; včetně 6ft HDMI + VGA adaptér..." },
        projectorLampHoursNotes: { label: "Hodiny lampy / životnost", hint: "U lampových jednotek: přibližné použité nebo zbývající hodiny. Měkká poznámka — ne reklamace záruky.", placeholder: "Lampa ~1200h použito / ~2000h rating; preferovat dim režim..." },
        projectorLightSource: { label: "Zdroj světla", hint: "Lampa, laser nebo LED — ovlivní nahřívání, outdoor použitelnost a riziko výměny." },
        projectorLumenBand: { label: "Jas (pásmo lumenů)", hint: "Přibližné ANSI / uváděné lumeny. Obývák potřebuje méně; světlé sály více. Měkké pásmo — ne laboratorní certifikát." },
        projectorNativeResBand: { label: "Nativní rozlišení", hint: "Nativní rozlišení panelu (ne max podporované). Nastaví očekávání ostrosti." },
        projectorPowerCableLengthBand: { label: "Délka napájecího kabelu", hint: "Délka přiloženého kabelu nebo prodlužovačky. Předejde překvapení u zásuvky na akci." },
        projectorScreenStandIncluded: { label: "Plátno / stojan v sadě?", hint: "Upřesněte, zda jde s jednotkou projekční plátno nebo stativ/stojan." },
        projectorThrowNotes: { label: "Throw / vzdálenost", hint: "Short-throw vs standard, typická vzdálenost pro danou velikost obrazu, strop vs stůl.", placeholder: "Short-throw ~3–5ft pro 100in; stůl OK; bez lens shift..." },
        projectorUseEnv: { label: "Indoor / outdoor použití", hint: "Prach, rosa a přímé slunce poškozují optiku — nastavte pravidlo před rezervací." },
        rackMountIncluded: { label: "Rack / mount sada", hint: "Zda jsou v sadě rack uši, wall plate, pole mount, nebo jen desktop." },
        rackMountKitIncluded: { label: "Rack ližiny / mount kit", hint: "Uveďte, zda jdou posuvné ližiny, cage nuts nebo cable arm. Pro tower/laptop WS použijte not-rack." },
        ramCapacityBand: { label: "Pásmo RAM", hint: "Měkké pásmo pro plánování — ne laboratorní měření." },
        remoteMgmtAccessPolicy: { label: "Přístup IPMI / iDRAC / iLO", hint: "Otevřené BMC způsobuje bezpečnostní spory — nastavte credentials, read-only, disabled nebo no-access." },
        renterFactoryRestorePolicy: { label: "Factory restore při vrácení", hint: "Zda musí nájemce obnovit tovární nastavení před vrácením, hostitel po, nebo leave-config OK (hostitel smaže)." },
        resolutionHdrBand: { label: "Rozlišení / HDR", hint: "Nativní rozlišení a HDR, které má nájemce řídit — SDR vs HDR10 / HLG / smíšená LED mapa." },
        returnFunctionTestAttest: { label: "Politika funkčního testu", hint: "Hostitel power-on / I/O smoke-test při inzerátu nebo předání; nájemce vrátí se stejným funkčním checkem." },
        returnFunctionTestPolicy: { label: "Funkční test při vrácení", hint: "Jak se ověří porty/preview/stream před uvolněním kauce." },
        returnWipeAckDepth: { label: "Hloubka potvrzení wipe při vrácení", hint: "Kdo resetuje nebo odhlašuje při vrácení — doplňuje wipe status hostitele pro celou privacy smyčku." },
        sampleRateBitDepthBand: { label: "Max sample-rate / bit-depth (měkké)", hint: "Doporučeno u digitálních interface/mixerů/recorderů. Měkké pásmo — ne laboratorní certifikát." },
        serverFormFactor: { label: "Form factor", hint: "Tower vs rack U vs laptop / AIO workstation — nastaví očekávání stůl vs colo vs mobilní WS." },
        serverPowerConfig: { label: "Napájení / PSU", hint: "120V vs 240V, jeden vs dual redundantní PSU, nebo PDU C13/C14. Měkká karta — ne partner energetiky." },
        shippingWeightNotes: { label: "Poznámky k dopravě / hmotnosti", hint: "Volitelné: přibližná hmotnost, jen osobní odběr, zvedání ve dvou, freight.", placeholder: "~25 kg 2U; jen osobní odběr; zvedání ve dvou..." },
        smartDeviceClass: { label: "Třída chytrého zařízení", hint: "Reproduktor/displej, kamera, zvonek, termostat, zámek, osvětlení, hub, senzory, nebo multi-device sada." },
        smartPowerType: { label: "Typ napájení", hint: "Zásuvka, baterie, hardwired, USB, PoE, nebo mixed kit — ovlivní instalaci a stav při vrácení." },
        smartProtocolBand: { label: "Pásmo protokolů", hint: "Zaškrtněte každé rádio / stack — Wi-Fi, Thread, Zigbee, Matter, Bluetooth, Z-Wave, nebo proprietary cloud." },
        speakerFormBand: { label: "Typ reproduktoru", hint: "Consumer/portable — Bluetooth portable, wired bookshelf, party boombox, soundbar nebo smart. Ne jevištní PA." },
        speakerPowerBand: { label: "Napájení", hint: "Jen baterie, AC síť, hybrid baterie+AC, nebo USB — zmrazí očekávání piknik vs zásuvka." },
        speakerWeatherBand: { label: "Venkovní / odolnost", hint: "Jen indoor vs splash-OK vs outdoor-rated — bazén a terasa způsobují vodní reklamace." },
        standMountIncluded: { label: "Stojan / držák v sadě?", hint: "Zda jde se reproduktorem podlahový stojan, tyč nebo nástěnný držák. Při ano zaškrtněte i stand_mount v inventáři." },
        stereoPairNotes: { label: "Poznámky k párování / stereo", hint: "Volitelné: TWS párování, stereo L/R, nebo druhá jednotka není v sadě.", placeholder: "PartyBoost / TWS s matching modelem OK; tento inzerát je jedna jednotka; druhý reproduktor není v ceně..." },
        transportFragilityBand: { label: "Křehkost při přepravě", hint: "Skleněné panely vs modulární LED vs rugged flight-case — nastaví balení a reklamace." },
        videoIoInventory: { label: "Inventář SDI / HDMI I/O", hint: "Porty na zařízení plus přiložené kabely/konvertory. Měkká patch karta.", placeholder: "4× HDMI in, 1× HDMI out, 1× SDI out; 3× HDMI + SDI↔HDMI konvertor…" },
